export const EXTRA_JS=String.raw`
(()=>{
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;const s=t.closest('section');if(!s)return;
if(t.matches('[data-pattern-jump]')){const dest=document.getElementById(t.hash.slice(1));if(dest){e.preventDefault();dest.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})}}
if(t.matches('[data-pattern-tab]')){const group=t.closest('.pattern-switcher');group.querySelectorAll('[data-pattern-tab]').forEach(x=>{x.setAttribute('aria-selected',x===t);x.tabIndex=x===t?0:-1});group.querySelectorAll('[role="tabpanel"]').forEach(x=>x.hidden=x.id!==t.getAttribute('aria-controls'))}
if(t.matches('[data-app-view]')){s.querySelectorAll('[data-app-view]').forEach(x=>x.setAttribute('aria-pressed',x===t));s.querySelector('[data-app-heading]').textContent=t.dataset.appView}
if(t.matches('[data-app-add]')){const input=s.querySelector('.app-task-input input'),list=s.querySelector('[data-app-tasks]');if(!input.value.trim()||list.children.length>=30)return;const li=document.createElement('li'),label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';label.append(check,document.createTextNode(input.value.trim()));li.append(label);list.append(li);input.value='';input.focus()}
if(t.matches('[data-release-filter]')){s.querySelectorAll('[data-release-filter]').forEach(x=>x.setAttribute('aria-pressed',x===t));s.querySelectorAll('[data-release-type]').forEach(x=>x.hidden=t.dataset.releaseFilter!=='全部'&&x.dataset.releaseType!==t.dataset.releaseFilter)}
});
document.addEventListener('input',e=>{if(!e.target.matches('[data-article-search]'))return;const s=e.target.closest('section'),q=e.target.value.toLocaleLowerCase().trim();let n=0;s.querySelectorAll('[data-article]').forEach(x=>{x.hidden=!x.textContent.toLocaleLowerCase().includes(q);if(!x.hidden)n++});s.querySelector('[data-article-empty]').hidden=n>0});
document.addEventListener('keydown',e=>{if(e.target.matches('.app-task-input input')&&e.key==='Enter'){e.preventDefault();e.target.nextElementSibling.click()}if(!e.target.matches('[data-pattern-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const list=[...e.target.parentElement.querySelectorAll('[data-pattern-tab]')],i=list.indexOf(e.target),n=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;list[n].click();list[n].focus()});
})();`;
